// === Tab: mySketch ===
let mainradius = 300;
let Yangle = 0;
let t = 0;

function setup() {
  createCanvas(800, 800, WEBGL);
  frameRate(60);
  smooth(8);
}

function draw() {
  background(0);
  translate(width / 2, height / 2);
  rotateX(HALF_PI);
  rotateZ(radians(-15));
  rotateY(Yangle);

  let latSteps = 100;
  let lonSteps = 200;

  for (i = 0; i < latSteps; i++) {
    let phi = map(i, 0, latSteps - 1, -HALF_PI, HALF_PI);
    let y = mainradius * sin(phi);
    let r = mainradius * cos(phi);

    for (j = 0; j < lonSteps; j++) {
      let theta = map(j, 0, lonSteps, 0, TWO_PI);
      let x = r * cos(theta);
      let z = r * sin(theta);

      // pattern binario pulsante
      let bandFreq = 8.0;
      let bandPhase = floor(sin(theta * bandFreq + t) * 2.0); // 0 o -1
      if (bandPhase == 0) continue;

      let dx = 0.8;
      let alpha = 255 * abs(sin(phi * 10 + t * 2));

      stroke(255, alpha);
      strokeWeight(0.4);
      line(x - dx, y, z, x + dx, y, z);
    }
  }

  t += 0.01;
  Yangle += 0.0025;
}

